using Preferis.Core.Routing;

namespace Preferis.Core.Configuration;

/// <summary>Creates the rule generated by the picker's "always use this choice for this host" option. See docs/Design.md §9.2.</summary>
public static class RememberedRule
{
    public static Rule Create(RoutingUrl url, string profileId) => new()
    {
        Id = $"remember-{url.Host}-{Guid.NewGuid().ToString("N")[..8]}",
        Name = url.Host,
        Condition = new HostCondition { Match = MatchKind.Exact, Pattern = url.Host },
        Actions = [new OpenAction { Profiles = [profileId] }],
    };

    /// <summary>
    /// Inserts the rule just before the rule that showed the picker, so that it takes precedence over it.
    /// When the picker came from the catch-all (<paramref name="beforeRuleId"/> is null) the rule is appended.
    /// </summary>
    public static void Insert(PreferisConfig config, Rule rule, string? beforeRuleId)
    {
        var index = beforeRuleId is null ? -1 : config.Rules.FindIndex(r => r.Id == beforeRuleId);
        if (index < 0)
        {
            config.Rules.Add(rule);
        }
        else
        {
            config.Rules.Insert(index, rule);
        }
    }
}
